import networkx as nx

try:
    G = nx.mcgee_graph()
    print("McGee graph found!")
    print("Nodes:", G.number_of_nodes())
    print("Edges:", G.number_of_edges())

    # Check girth
    def get_girth(G):
        girth = float('inf')
        for n in G.nodes():
            # BFS to find shortest cycle
            dist = {n: 0}
            parent = {n: None}
            q = [n]
            while q:
                u = q.pop(0)
                for v in G.neighbors(u):
                    if v not in dist:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        q.append(v)
                    elif parent[u] != v:
                        girth = min(girth, dist[u] + dist[v] + 1)
        return girth

    print("Girth:", get_girth(G))

    # Check 3-colorability
    coloring = nx.coloring.greedy_color(G, strategy='largest_first')
    num_colors = max(coloring.values()) + 1
    print("Colors:", num_colors)

    edges = list(G.edges())
    print("Edges list:", edges)
except Exception as e:
    print("Error:", e)

