def is_3_colorable(adj, V):
    # Backtracking to check 3-colorability
    colors = [-1] * V
    def color(u):
        if u == V:
            return True
        used = set(colors[v] for v in adj[u] if colors[v] != -1)
        for c in range(3):
            if c not in used:
                colors[u] = c
                if color(u + 1):
                    return True
                colors[u] = -1
        return False
    return color(0)

